-- QAtlas initial schema (docs/03-domain-model.md, docs/13-implementation-guide.md).
--
-- Conventions
--   * Primary keys are uuid v7 generated by the application (db.NewID); there is
--     deliberately no DEFAULT so every insert path uses sortable ids.
--   * Enums are text + CHECK constraints (easier to extend than Postgres enum types:
--     a new value is a one-line constraint swap in a later migration).
--   * Emails are stored lowercased (CHECK) with a plain unique index instead of citext,
--     so no extension is required.
--   * Times are timestamptz; updated_at is maintained by the application.
--   * River (job queue) tables are NOT part of this file. The worker package adds them
--     through rivermigrate in a later step; keep River's own migration line separate.

-- +goose Up

-- ------------------------------------------------------------------ identity & access

CREATE TABLE users (
    id            uuid PRIMARY KEY,
    email         text        NOT NULL CHECK (email <> '' AND email = lower(email)),
    name          text        NOT NULL,
    password_hash text,
    google_sub    text,
    system_role   text        NOT NULL DEFAULT 'member' CHECK (system_role IN ('admin', 'member')),
    status        text        NOT NULL DEFAULT 'invited' CHECK (status IN ('invited', 'active', 'disabled')),
    locale        text        NOT NULL DEFAULT 'en' CHECK (locale IN ('en', 'id')),
    last_login_at timestamptz,
    created_at    timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX users_email_key ON users (email);
CREATE UNIQUE INDEX users_google_sub_key ON users (google_sub) WHERE google_sub IS NOT NULL;

-- One-time links: kind=invite (set first password) or reset_password (admin-generated).
CREATE TABLE invites (
    id         uuid PRIMARY KEY,
    user_id    uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    kind       text        NOT NULL CHECK (kind IN ('invite', 'reset_password')),
    token_hash bytea       NOT NULL,
    expires_at timestamptz NOT NULL,
    used_at    timestamptz,
    created_by uuid REFERENCES users (id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX invites_token_hash_key ON invites (token_hash);
CREATE INDEX invites_open_by_user_idx ON invites (user_id) WHERE used_at IS NULL;

-- Web sessions (cookie qatlas_session). token_hash = sha256(cookie value).
-- Sliding expiry: expires_at = min(last_seen_at + 7d, created_at + 30d).
CREATE TABLE sessions (
    id           uuid PRIMARY KEY,
    user_id      uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    token_hash   bytea       NOT NULL,
    user_agent   text        NOT NULL DEFAULT '',
    ip           text        NOT NULL DEFAULT '',
    created_at   timestamptz NOT NULL DEFAULT now(),
    last_seen_at timestamptz NOT NULL DEFAULT now(),
    expires_at   timestamptz NOT NULL
);
CREATE UNIQUE INDEX sessions_token_hash_key ON sessions (token_hash);
CREATE INDEX sessions_user_id_idx ON sessions (user_id);
CREATE INDEX sessions_expires_at_idx ON sessions (expires_at);

-- API tokens qat_<8 hex>_<32 hex>. prefix = "qat_<8 hex>" (shown in UI), token_hash = sha256(full secret).
-- project_ids NULL = every project the owner can access.
CREATE TABLE api_tokens (
    id           uuid PRIMARY KEY,
    user_id      uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    name         text        NOT NULL CHECK (name <> ''),
    prefix       text        NOT NULL,
    token_hash   bytea       NOT NULL,
    scopes       text[]      NOT NULL CHECK (cardinality(scopes) > 0 AND scopes <@ ARRAY['read', 'write', 'run']::text[]),
    project_ids  uuid[],
    expires_at   timestamptz,
    last_used_at timestamptz,
    revoked_at   timestamptz,
    created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX api_tokens_prefix_key ON api_tokens (prefix);
CREATE UNIQUE INDEX api_tokens_token_hash_key ON api_tokens (token_hash);
CREATE INDEX api_tokens_user_id_idx ON api_tokens (user_id, created_at DESC);

-- Password login attempts, used for rate limiting (10 failures / 15 min per email+IP).
-- Rows older than a day are pruned opportunistically by the auth service.
CREATE TABLE login_attempts (
    id         bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    email      text        NOT NULL,
    ip         text        NOT NULL,
    success    boolean     NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX login_attempts_email_ip_idx ON login_attempts (email, ip, created_at DESC);
CREATE INDEX login_attempts_ip_idx ON login_attempts (ip, created_at DESC);
CREATE INDEX login_attempts_created_at_idx ON login_attempts (created_at);

-- ------------------------------------------------------------------ projects

CREATE TABLE projects (
    id                      uuid PRIMARY KEY,
    key                     text        NOT NULL CHECK (key ~ '^[A-Z][A-Z0-9]{1,9}$'),
    name                    text        NOT NULL CHECK (name <> ''),
    description             text        NOT NULL DEFAULT '',
    archived_at             timestamptz,
    created_by              uuid REFERENCES users (id) ON DELETE SET NULL,
    default_run_options     jsonb       NOT NULL DEFAULT '{"browser":"chromium","headless":true,"viewport":{"width":1280,"height":720},"screenshot":"on_failure","video":"off","step_timeout_ms":10000,"retries":0}'::jsonb,
    artifact_retention_days integer     NOT NULL DEFAULT 30 CHECK (artifact_retention_days > 0),
    -- Per-project key counters: UPDATE projects SET seq_case = seq_case + 1 ... RETURNING seq_case
    -- inside the creating transaction (SHOP-T12, SHOP-F3, SHOP-R105).
    seq_case                integer     NOT NULL DEFAULT 0,
    seq_flow                integer     NOT NULL DEFAULT 0,
    seq_run                 integer     NOT NULL DEFAULT 0,
    created_at              timestamptz NOT NULL DEFAULT now(),
    updated_at              timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX projects_key_key ON projects (key);

CREATE TABLE project_members (
    project_id uuid        NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    user_id    uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    role       text        NOT NULL CHECK (role IN ('maintainer', 'editor', 'viewer')),
    added_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (project_id, user_id)
);
CREATE INDEX project_members_user_id_idx ON project_members (user_id);

CREATE TABLE environments (
    id         uuid PRIMARY KEY,
    project_id uuid        NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    name       text        NOT NULL CHECK (name <> ''),
    is_default boolean     NOT NULL DEFAULT false,
    variables  jsonb       NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(variables) = 'object'),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX environments_project_name_key ON environments (project_id, name);
-- At most one default environment per project.
CREATE UNIQUE INDEX environments_one_default_idx ON environments (project_id) WHERE is_default;

-- value_enc = AES-256-GCM(nonce || ciphertext) with QATLAS_MASTER_KEY. Never returned by the API.
CREATE TABLE environment_secrets (
    environment_id uuid        NOT NULL REFERENCES environments (id) ON DELETE CASCADE,
    name           text        NOT NULL CHECK (name ~ '^[A-Z][A-Z0-9_]*$'),
    value_enc      bytea       NOT NULL,
    created_at     timestamptz NOT NULL DEFAULT now(),
    updated_at     timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (environment_id, name)
);

-- ------------------------------------------------------------------ test management

-- Deleting a folder re-parents children and test cases first (application logic, see mock).
CREATE TABLE folders (
    id         uuid PRIMARY KEY,
    project_id uuid        NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    parent_id  uuid REFERENCES folders (id),
    name       text        NOT NULL CHECK (name <> ''),
    position   integer     NOT NULL DEFAULT 0,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CHECK (parent_id IS DISTINCT FROM id)
);
CREATE INDEX folders_project_parent_idx ON folders (project_id, parent_id, position);

CREATE TABLE test_cases (
    id              uuid PRIMARY KEY,
    project_id      uuid        NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    seq             integer     NOT NULL CHECK (seq > 0),
    folder_id       uuid REFERENCES folders (id) ON DELETE SET NULL,
    title           text        NOT NULL CHECK (title <> ''),
    description     text        NOT NULL DEFAULT '',
    preconditions   text        NOT NULL DEFAULT '',
    priority        text        NOT NULL DEFAULT 'medium' CHECK (priority IN ('low', 'medium', 'high', 'critical')),
    status          text        NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'ready', 'deprecated')),
    execution       text        NOT NULL DEFAULT 'automated' CHECK (execution IN ('automated', 'manual')),
    tags            text[]      NOT NULL DEFAULT '{}',
    variables       jsonb       NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(variables) = 'object'),
    steps           jsonb       NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(steps) = 'array'),
    revision        integer     NOT NULL DEFAULT 1 CHECK (revision > 0),
    -- Denormalised from the latest run touching this case (list view filter last_run_status).
    last_run_status text CHECK (last_run_status IN ('queued', 'running', 'awaiting_manual', 'passed', 'failed', 'blocked', 'error', 'cancelled')),
    last_run_at     timestamptz,
    created_by      uuid REFERENCES users (id) ON DELETE SET NULL,
    updated_by      uuid REFERENCES users (id) ON DELETE SET NULL,
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now(),
    deleted_at      timestamptz
);
CREATE UNIQUE INDEX test_cases_project_seq_key ON test_cases (project_id, seq);
CREATE INDEX test_cases_project_folder_idx ON test_cases (project_id, folder_id) WHERE deleted_at IS NULL;
CREATE INDEX test_cases_tags_idx ON test_cases USING gin (tags);

CREATE TABLE test_case_revisions (
    test_case_id uuid        NOT NULL REFERENCES test_cases (id) ON DELETE CASCADE,
    revision     integer     NOT NULL CHECK (revision > 0),
    snapshot     jsonb       NOT NULL,
    author_id    uuid REFERENCES users (id) ON DELETE SET NULL,
    change_note  text        NOT NULL DEFAULT '',
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (test_case_id, revision)
);

CREATE TABLE flows (
    id              uuid PRIMARY KEY,
    project_id      uuid        NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    seq             integer     NOT NULL CHECK (seq > 0),
    name            text        NOT NULL CHECK (name <> ''),
    description     text        NOT NULL DEFAULT '',
    tags            text[]      NOT NULL DEFAULT '{}',
    shared_session  boolean     NOT NULL DEFAULT false,
    stop_on_failure boolean     NOT NULL DEFAULT true,
    variables       jsonb       NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(variables) = 'object'),
    revision        integer     NOT NULL DEFAULT 1 CHECK (revision > 0),
    last_run_status text CHECK (last_run_status IN ('queued', 'running', 'awaiting_manual', 'passed', 'failed', 'blocked', 'error', 'cancelled')),
    last_run_at     timestamptz,
    created_by      uuid REFERENCES users (id) ON DELETE SET NULL,
    updated_by      uuid REFERENCES users (id) ON DELETE SET NULL,
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now(),
    deleted_at      timestamptz
);
CREATE UNIQUE INDEX flows_project_seq_key ON flows (project_id, seq);
CREATE INDEX flows_project_idx ON flows (project_id) WHERE deleted_at IS NULL;

-- Items are replaced wholesale on flow update (mock behaviour), position is 1-based.
CREATE TABLE flow_items (
    id                  uuid PRIMARY KEY,
    flow_id             uuid    NOT NULL REFERENCES flows (id) ON DELETE CASCADE,
    position            integer NOT NULL CHECK (position > 0),
    test_case_id        uuid    NOT NULL REFERENCES test_cases (id),
    continue_on_failure boolean NOT NULL DEFAULT false,
    enabled             boolean NOT NULL DEFAULT true
);
CREATE UNIQUE INDEX flow_items_flow_position_key ON flow_items (flow_id, position);
CREATE INDEX flow_items_test_case_idx ON flow_items (test_case_id);

-- ------------------------------------------------------------------ execution

CREATE TABLE runs (
    id               uuid PRIMARY KEY,
    project_id       uuid        NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    seq              integer     NOT NULL CHECK (seq > 0),
    kind             text        NOT NULL CHECK (kind IN ('test_case', 'flow')),
    test_case_id     uuid REFERENCES test_cases (id),
    flow_id          uuid REFERENCES flows (id),
    -- Display snapshot of the target / environment at creation time (RunSummary.target, .environment).
    target_key       text        NOT NULL,
    target_title     text        NOT NULL,
    environment_id   uuid REFERENCES environments (id) ON DELETE SET NULL,
    environment_name text,
    status           text        NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'running', 'awaiting_manual', 'passed', 'failed', 'blocked', 'error', 'cancelled')),
    trigger          text        NOT NULL DEFAULT 'manual' CHECK (trigger IN ('manual', 'mcp', 'api', 'schedule')),
    triggered_by     uuid        NOT NULL REFERENCES users (id),
    api_token_id     uuid REFERENCES api_tokens (id) ON DELETE SET NULL,
    assignee_id      uuid REFERENCES users (id),
    shared_session   boolean     NOT NULL DEFAULT false,
    stop_on_failure  boolean     NOT NULL DEFAULT true,
    -- Flow position (run_cases.position) to continue from after a manual case completes.
    resume_position  integer CHECK (resume_position > 0),
    cancel_requested boolean     NOT NULL DEFAULT false,
    options          jsonb       NOT NULL CHECK (jsonb_typeof(options) = 'object'),
    -- Test case(s) with steps, flow options, env name + variables, secret NAMES only.
    snapshot         jsonb       NOT NULL DEFAULT '{}'::jsonb,
    error_message    text,
    queued_at        timestamptz NOT NULL DEFAULT now(),
    started_at       timestamptz,
    finished_at      timestamptz,
    created_at       timestamptz NOT NULL DEFAULT now(),
    updated_at       timestamptz NOT NULL DEFAULT now(),
    CHECK ((kind = 'test_case' AND test_case_id IS NOT NULL AND flow_id IS NULL)
        OR (kind = 'flow' AND flow_id IS NOT NULL AND test_case_id IS NULL))
);
CREATE UNIQUE INDEX runs_project_seq_key ON runs (project_id, seq);
CREATE INDEX runs_project_queued_idx ON runs (project_id, queued_at DESC);
CREATE INDEX runs_test_case_idx ON runs (test_case_id, queued_at DESC) WHERE test_case_id IS NOT NULL;
CREATE INDEX runs_flow_idx ON runs (flow_id, queued_at DESC) WHERE flow_id IS NOT NULL;
CREATE INDEX runs_awaiting_assignee_idx ON runs (assignee_id, queued_at) WHERE status = 'awaiting_manual';
CREATE INDEX runs_active_idx ON runs (status) WHERE status IN ('queued', 'running');

CREATE TABLE run_cases (
    id                  uuid PRIMARY KEY,
    run_id              uuid        NOT NULL REFERENCES runs (id) ON DELETE CASCADE,
    position            integer     NOT NULL CHECK (position > 0),
    test_case_id        uuid        NOT NULL REFERENCES test_cases (id),
    test_case_key       text        NOT NULL,
    test_case_revision  integer     NOT NULL,
    title               text        NOT NULL,
    execution           text        NOT NULL CHECK (execution IN ('automated', 'manual')),
    continue_on_failure boolean     NOT NULL DEFAULT false,
    status              text        NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'running', 'passed', 'failed', 'blocked', 'skipped', 'error')),
    executed_by         uuid REFERENCES users (id),
    started_at          timestamptz,
    finished_at         timestamptz,
    duration_ms         integer,
    video_artifact_id   uuid -- FK added below (artifacts references run_cases)
);
CREATE UNIQUE INDEX run_cases_run_position_key ON run_cases (run_id, position);
CREATE INDEX run_cases_test_case_idx ON run_cases (test_case_id);

CREATE TABLE run_steps (
    id                     uuid PRIMARY KEY,
    run_case_id            uuid    NOT NULL REFERENCES run_cases (id) ON DELETE CASCADE,
    position               integer NOT NULL CHECK (position > 0),
    step_id                text    NOT NULL, -- DSL step id from the test case
    action                 text    NOT NULL,
    summary                text    NOT NULL DEFAULT '', -- dsl.Summarize, env interpolated, secrets masked
    description            text    NOT NULL DEFAULT '',
    expected               text    NOT NULL DEFAULT '',
    continue_on_failure    boolean NOT NULL DEFAULT false,
    enabled                boolean NOT NULL DEFAULT true,
    status                 text    NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'running', 'passed', 'failed', 'blocked', 'skipped', 'error')),
    duration_ms            integer,
    error_message          text,
    actual_result          text, -- tester notes (manual steps)
    screenshot_artifact_id uuid, -- FK added below
    details                jsonb, -- {expected, actual} or {request, response}
    started_at             timestamptz,
    finished_at            timestamptz
);
CREATE UNIQUE INDEX run_steps_case_position_key ON run_steps (run_case_id, position);

CREATE TABLE artifacts (
    id          uuid PRIMARY KEY,
    project_id  uuid        NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    run_id      uuid        NOT NULL REFERENCES runs (id) ON DELETE CASCADE,
    run_case_id uuid REFERENCES run_cases (id) ON DELETE CASCADE,
    run_step_id uuid REFERENCES run_steps (id) ON DELETE SET NULL,
    kind        text        NOT NULL CHECK (kind IN ('screenshot', 'video', 'trace', 'log', 'attachment')),
    name        text        NOT NULL DEFAULT '',
    storage_key text        NOT NULL,
    mime        text        NOT NULL DEFAULT 'application/octet-stream',
    size_bytes  bigint      NOT NULL DEFAULT 0 CHECK (size_bytes >= 0),
    uploaded_by uuid REFERENCES users (id) ON DELETE SET NULL, -- tester attachments
    expires_at  timestamptz, -- retention deadline (project.artifact_retention_days)
    purged_at   timestamptz, -- file removed by the retention job => Artifact.expired = true
    created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX artifacts_run_idx ON artifacts (run_id);
CREATE INDEX artifacts_run_case_idx ON artifacts (run_case_id) WHERE run_case_id IS NOT NULL;
CREATE INDEX artifacts_expiry_idx ON artifacts (expires_at) WHERE purged_at IS NULL;

ALTER TABLE run_cases
    ADD CONSTRAINT run_cases_video_artifact_fk FOREIGN KEY (video_artifact_id) REFERENCES artifacts (id) ON DELETE SET NULL;
ALTER TABLE run_steps
    ADD CONSTRAINT run_steps_screenshot_artifact_fk FOREIGN KEY (screenshot_artifact_id) REFERENCES artifacts (id) ON DELETE SET NULL;

-- ------------------------------------------------------------------ audit

CREATE TABLE audit_logs (
    id             uuid PRIMARY KEY,
    actor_user_id  uuid REFERENCES users (id) ON DELETE SET NULL,
    actor_token_id uuid REFERENCES api_tokens (id) ON DELETE SET NULL,
    project_id     uuid REFERENCES projects (id) ON DELETE SET NULL,
    action         text        NOT NULL, -- e.g. auth.login, user.update, test_case.update
    entity_type    text        NOT NULL,
    entity_id      text        NOT NULL DEFAULT '', -- uuid or display key
    meta           jsonb       NOT NULL DEFAULT '{}'::jsonb,
    created_at     timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX audit_logs_created_idx ON audit_logs (created_at DESC);
CREATE INDEX audit_logs_project_idx ON audit_logs (project_id, created_at DESC) WHERE project_id IS NOT NULL;
CREATE INDEX audit_logs_actor_idx ON audit_logs (actor_user_id, created_at DESC);
CREATE INDEX audit_logs_entity_idx ON audit_logs (entity_type, entity_id);

-- +goose Down

DROP TABLE IF EXISTS audit_logs;
ALTER TABLE IF EXISTS run_steps DROP CONSTRAINT IF EXISTS run_steps_screenshot_artifact_fk;
ALTER TABLE IF EXISTS run_cases DROP CONSTRAINT IF EXISTS run_cases_video_artifact_fk;
DROP TABLE IF EXISTS artifacts;
DROP TABLE IF EXISTS run_steps;
DROP TABLE IF EXISTS run_cases;
DROP TABLE IF EXISTS runs;
DROP TABLE IF EXISTS flow_items;
DROP TABLE IF EXISTS flows;
DROP TABLE IF EXISTS test_case_revisions;
DROP TABLE IF EXISTS test_cases;
DROP TABLE IF EXISTS folders;
DROP TABLE IF EXISTS environment_secrets;
DROP TABLE IF EXISTS environments;
DROP TABLE IF EXISTS project_members;
DROP TABLE IF EXISTS projects;
DROP TABLE IF EXISTS login_attempts;
DROP TABLE IF EXISTS api_tokens;
DROP TABLE IF EXISTS sessions;
DROP TABLE IF EXISTS invites;
DROP TABLE IF EXISTS users;
